<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Invoice; use App\Services\Invoices\InvoiceService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class InvoiceController extends Controller {
 public function index(Request $r){$q=Invoice::where('company_id',$r->user()->company_id)->with('client');if($r->filled('status'))$q->where('status',$r->status);if($r->filled('search'))$q->where('invoice_number','like','%'.$r->search.'%');return $q->latest('issue_date')->paginate($r->integer('per_page',20));}
 public function store(Request $r,InvoiceService $service){$data=$r->validate(['branch_id'=>['nullable','exists:branches,id',function($attribute,$value,$fail)use($r){if($value && !\App\Models\Branch::where('company_id',$r->user()->company_id)->whereKey($value)->exists())$fail('The selected branch is invalid.');}],'client_id'=>['required','exists:clients,id',function($attribute,$value,$fail)use($r){if($value && !\App\Models\Client::where('company_id',$r->user()->company_id)->whereKey($value)->exists())$fail('The selected client is invalid.');}],'sale_id'=>['nullable','exists:sales,id',function($attribute,$value,$fail)use($r){if($value && !\App\Models\Sale::where('company_id',$r->user()->company_id)->whereKey($value)->exists())$fail('The selected sale is invalid.');}],'issue_date'=>'nullable|date','due_date'=>'nullable|date|after_or_equal:issue_date','discount'=>'nullable|numeric|min:0','notes'=>'nullable|string','items'=>'required|array|min:1','items.*.product_id'=>'nullable|exists:products,id','items.*.description'=>'nullable|string','items.*.quantity'=>'required|numeric|min:0.001','items.*.unit_price'=>'required|numeric|min:0','items.*.discount'=>'nullable|numeric|min:0','items.*.tax_rate'=>'nullable|numeric|min:0']);return response()->json($service->create($data,$r->user()),201);}
 public function show(Request $r,Invoice $invoice){abort_unless($invoice->company_id===$r->user()->company_id,404);return $invoice->load('client','sale','items.product','allocations.payment');}
 public function update(Request $r,Invoice $invoice){abort_unless($invoice->company_id===$r->user()->company_id,404);if((float)$invoice->amount_paid>0 && $r->input('status')==='cancelled')abort(422,'Paid invoices cannot be cancelled.');if($invoice->status==='cancelled' && $r->input('status')!=='cancelled')abort(422,'Cancelled invoices cannot be reopened.');$data=$r->validate(['due_date'=>'nullable|date','status'=>'nullable|in:draft,issued,cancelled','notes'=>'nullable|string']);if(($data['status']??null)==='cancelled'){$data['amount_paid']=0;$data['balance']=0;} $invoice->update($data);return $invoice->fresh();}
 public function destroy(Request $r,Invoice $invoice){abort_unless($invoice->company_id===$r->user()->company_id,404);if((float)$invoice->amount_paid>0 || $invoice->status==='cancelled')abort(422,'Paid or cancelled invoices cannot be deleted.');$invoice->delete();return response()->noContent();}
}
